export const LINES = [["From the start?", 5.52, 6.16], ["All right.", 6.52, 6.96], ["A year ago I had forty windows open and couldn't find anything.", 7.934, 11.174], ["Then I installed a small program called Spaceman.", 11.534, 14.334], ["It tiles your windows.", 14.654, 16.174], ["They sit side by side, nothing on top of anything else, and they stay just where you put them.", 16.494, 21.737], ["It also gives you numbered workspaces.", 22.097, 24.17], ["If something's in the wrong place, you don't close it — you just move it to another number.", 24.505, 28.11], ["My work went on one, and my messages on two.", 28.47, 31.06], ["I had a camera on my front door, and that's only another window, so I put it on three.", 31.421, 35.565], ["You can float a window too, if you want to keep an eye on it.", 35.906, 38.556], ["I found it pleasing.", 38.986, 39.971], ["So I bought one or two more, and I gave each of my neighbours a workspace of their own.", 46.506, 50.736], ["Mark is four.", 51.136, 52.176], ["Joan is five.", 52.496, 53.656], ["Alan is six.", 54.016, 54.856], ["I like to know my neighbours.", 55.508, 56.823], ["Alan's hedge was a little over the limit, so I took a few photographs, for the record.", 59.848, 64.268], ["And Joan and I disagreed about which day the bins go out.", 70.088, 72.968], ["I'd kept seven empty, because it's useful to have somewhere to put things.", 77.288, 80.64], ["I moved Joan there in March, and I've looked after her cat ever since.", 81.0, 84.678], ["I moved Mark in June.", 86.838, 88.278], ["Where is Alan now?", 89.403, 90.768], ["He's on seven, with the other two.", 91.663, 93.623], ["And what is on seven?", 95.318, 96.836], ["Only the one window.", 97.681, 98.894], ["They're side by side, nothing on top of anything else, and they stay just where I put them.", 99.199, 104.254], ["You should try it, Detective.", 106.399, 107.827], ["You look like a woman with a great many windows open.", 108.247, 110.567]]
